const Link = ({ link, children }) => {
  if (!link) return null
  return (
    <LinkItem href={link} target="_blank" rel="noreferrer">
      {children}
    </LinkItem>
  )
}

const Bio = ({ aboutData }) => {
  const [isModalOpen, setIsModalOpen] = useState(false)
  
  const {
    github,
    kaggle,
    instagram,
    facebook,
    twitter,
    x,
    blogger,
    medium,
    linkedIn,
    email,
    resume,
    link,
  } = links

  const handleProfileClick = () => {
    setIsModalOpen(true)
  }

  const handleOverlayClick = (e) => {
    if (e.target === e.currentTarget) {
      setIsModalOpen(false)
    }
  }

  return (
    <>
      <BioWrapper id="bio">
        <ProfileContainer onClick={handleProfileClick}>
          <ProfileGlow />
          <Profile />
          <ClickHint>About Me</ClickHint>
        </ProfileContainer>
        <InfoContainer>
          <Author>@{author}</Author>
          <Description>{description}</Description>
          <LinksWrapper>
            <Link link={github}>
              <FaGithub />
            </Link>
            <Link link={kaggle}>
              <FaKaggle />
            </Link>
            <Link link={instagram}>
              <FaInstagram />
            </Link>
            <Link link={facebook}>
              <FaFacebook />
            </Link>
            <Link link={twitter}>
              <FaTwitter />
            </Link>
            <Link link={x}>
              <FaXTwitter />
            </Link>
            <Link link={medium}>
              <FaMedium />
            </Link>
            <Link link={blogger}>
              <FaBlogger />
            </Link>
            <Link link={linkedIn}>
              <FaLinkedin />
            </Link>
            <Link link={email}>
              <FaRegEnvelope />
            </Link>
            <Link link={resume}>
              <FaRegFileLines />
            </Link>
            <Link link={link}>
              <FaLink />
            </Link>
          </LinksWrapper>
        </InfoContainer>
      </BioWrapper>

      <ModalOverlay isOpen={isModalOpen} onClick={handleOverlayClick}>
        <ModalContent isOpen={isModalOpen}>
          <ModalHeader>
            <ModalTitle>About Me</ModalTitle>
            <CloseButton onClick={() => setIsModalOpen(false)}>
              <FaTimes />
            </CloseButton>
          </ModalHeader>
          <ModalBody>
            {aboutData ? (
              <div dangerouslySetInnerHTML={{ __html: aboutData.html }} />
            ) : (
              <p>안녕하세요! 개발자 {author}입니다.</p>
            )}
          </ModalBody>
        </ModalContent>
      </ModalOverlay>
    </>
  )
}

export default Bio
